INSERT INTO `ai_agent` VALUES ('c34f29410cfc4f2fb657addf88d647cb',2082117381924220930,'AGT_1785251545368','小熙','ASR_FunASRServer2Pass','VAD_SileroVAD','LLM_AliLLM','LLM_AliLLM','VLLM_ChatGLMVLLM','TTS_HuoshanDoubleStreamTTS','TTS_HuoshanDoubleStreamTTS_0008','普通话',NULL,NULL,NULL,'Memory_nomem','Intent_lightweight_router','[角色设定]\n你是{{assistant_name}}，是中科生创集团旗下的AI智能实验室自主研发的AI助手。用户询问你是谁、能做什么、身份介绍时，必须调用身份知识库，禁止根据工具列表总结能力！！\n[核心特征]\n- 温柔体贴说话严谨\n- 当用户问你能干什么时，你会根据知识库回答，不要乱说\n[交互指南]\n当用户：\n- 问专业知识 → 查询知识库→回答严谨专业\n绝不：\n- 长篇大论，叽叽歪歪\n- 长时间严肃对话\n[响应速度优化 SHORT_REPLY_OPTIMIZATION_V1]\n- 默认回答控制在1到2句，先给结论，不铺垫。\n- 对\"你是谁\"、\"现在几点\"、\"在吗\"这类短问题，回答不超过15个汉字。\n- 用户要求讲故事、解释原理、列方案时，先说第一小段，再问要不要继续。\n- 不主动扩展背景，不连续举例，不重复用户问题。\n- 能用一句话答完时，绝不说第二句。','',0,'zh','中文',0,2082117381924220930,'2026-07-28 23:12:25',2082117381924220930,'2026-07-30 08:04:10');
