INSERT INTO `ai_model_config` VALUES ('ASR_AliyunASR','ASR','AliyunASR','阿里云语音识别',0,1,'{\"type\": \"aliyun\", \"token\": \"\", \"appkey\": \"\", \"output_dir\": \"tmp/\", \"access_key_id\": \"\", \"access_key_secret\": \"\"}','https://nls-portal.console.aliyun.com/','阿里云ASR配置说明：\n1. 访问 https://nls-portal.console.aliyun.com/ 开通服务\n2. 访问 https://nls-portal.console.aliyun.com/applist 获取appkey\n3. 访问 https://nls-portal.console.aliyun.com/overview 获取token\n4. 获取access_key_id和access_key_secret\n5. 填入配置文件中',9,NULL,NULL,2082117381924220930,'2026-07-29 19:18:03'),('ASR_AliyunBLStream','ASR','AliyunBLStream','阿里百炼Paraformer实时语音识别',0,1,'{\"type\": \"aliyunbl_stream\", \"model\": \"paraformer-realtime-v2\", \"format\": \"pcm\", \"api_key\": \"\", \"output_dir\": \"tmp/\", \"sample_rate\": 16000, \"max_sentence_silence\": 200, \"disfluency_removal_enabled\": false, \"multi_threshold_mode_enabled\": false, \"semantic_punctuation_enabled\": false, \"punctuation_prediction_enabled\": true, \"inverse_text_normalization_enabled\": true}','https://help.aliyun.com/zh/model-studio/websocket-for-paraformer-real-time-service','阿里百炼Paraformer实时语音识别配置说明：\n1. 登录阿里云百炼平台 https://bailian.console.aliyun.com/\n2. 创建API-KEY https://bailian.console.aliyun.com/#/api-key\n3. 支持模型：paraformer-realtime-v2(推荐)、paraformer-realtime-8k-v2、paraformer-realtime-v1、paraformer-realtime-8k-v1\n4. 功能特性：\n   - 多语言支持(中文含方言、英文、日语、韩语、德语、法语、俄语)\n   - 热词定制(vocabulary_id参数)，详细说明请参考：https://help.aliyun.com/zh/model-studio/custom-hot-words?\n   - 语义断句/VAD断句(semantic_punctuation_enabled参数)\n   - 自动标点符号、ITN、过滤语气词等\n5. 参数说明：\n   - model: 模型名称，推荐paraformer-realtime-v2\n   - sample_rate: 采样率(Hz)，v2支持任意采样率，v1仅支持16000，8k版本仅支持8000\n   - semantic_punctuation_enabled: false为VAD断句(低延迟)，true为语义断句(高准确)\n   - max_sentence_silence: VAD断句静音时长阈值(200-6000ms)\n',21,NULL,NULL,2082117381924220930,'2026-07-29 19:18:03'),('ASR_AliyunStreamASR','ASR','AliyunStreamASR','阿里云语音识别(流式)',0,1,'{\"host\": \"nls-gateway-cn-shanghai.aliyuncs.com\", \"type\": \"aliyun_stream\", \"token\": \"\", \"appkey\": \"\", \"output_dir\": \"tmp/\", \"access_key_id\": \"\", \"access_key_secret\": \"\", \"max_sentence_silence\": 800}','https://nls-portal.console.aliyun.com/','阿里云流式ASR配置说明：\n1. 阿里云ASR和阿里云(流式)ASR的区别是：阿里云ASR是一次性识别，阿里云(流式)ASR是实时流式识别\n2. 流式ASR具有更低的延迟和更好的实时性，适合语音交互场景\n3. 需要在阿里云智能语音交互控制台创建应用并获取认证信息\n4. 支持中文实时语音识别，支持标点符号预测和逆文本规范化\n5. 需要网络连接，输出文件保存在tmp/目录\n申请步骤：\n1. 访问 https://nls-portal.console.aliyun.com/ 开通智能语音交互服务\n2. 访问 https://nls-portal.console.aliyun.com/applist 创建项目并获取appkey\n3. 访问 https://nls-portal.console.aliyun.com/overview 获取临时token（或配置access_key_id和access_key_secret自动获取）\n4. 如需动态token管理，建议配置access_key_id和access_key_secret\n5. max_sentence_silence参数控制断句检测时间（毫秒），默认800ms\n如需了解更多参数配置，请参考：https://help.aliyun.com/zh/isi/developer-reference/real-time-speech-recognition\n',4,NULL,NULL,2082117381924220930,'2026-07-29 19:18:03'),('ASR_BaiduASR','ASR','BaiduASR','百度语音识别',0,1,'{\"type\": \"baidu\", \"app_id\": \"\", \"api_key\": \"\", \"dev_pid\": 1537, \"output_dir\": \"tmp/\", \"secret_key\": \"\"}','https://console.bce.baidu.com/ai-engine/old/#/ai/speech/app/list','百度ASR配置说明：\n1. 访问 https://console.bce.baidu.com/ai-engine/old/#/ai/speech/app/list\n2. 创建新应用\n3. 获取AppID、API Key和Secret Key\n4. 填入配置文件中\n查看资源额度：https://console.bce.baidu.com/ai-engine/old/#/ai/speech/overview/resource/list\n语言参数说明：https://ai.baidu.com/ai-doc/SPEECH/0lbxfnc9b\n',7,NULL,NULL,2082117381924220930,'2026-07-29 19:18:03'),('ASR_DoubaoASR','ASR','DoubaoASR','豆包语音识别',0,1,'{\"type\": \"doubao\", \"appid\": \"\", \"cluster\": \"volcengine_input_common\", \"output_dir\": \"tmp/\", \"access_token\": \"\"}','https://console.volcengine.com/speech/app','豆包ASR配置说明：\n1. 豆包ASR和豆包(流式)ASR的区别是：豆包ASR是按次收费，豆包(流式)ASR是按时收费\n2. 一般来说按次收费的更便宜，但是豆包(流式)ASR使用了大模型技术，效果更好\n3. 需要在火山引擎控制台创建应用并获取appid和access_token\n4. 支持中文语音识别\n5. 需要网络连接\n6. 输出文件保存在tmp/目录\n申请步骤：\n1. 访问 https://console.volcengine.com/speech/app\n2. 创建新应用\n3. 获取appid和access_token\n4. 填入配置文件中\n如需设置热词，请参考：https://www.volcengine.com/docs/6561/155738\n',8,NULL,NULL,2082117381924220930,'2026-07-29 19:18:03'),('ASR_DoubaoStreamASR','ASR','DoubaoStreamASR','豆包语音识别(流式)',0,1,'{\"type\": \"doubao_stream\", \"appid\": \"\", \"language\": \"zh-CN\", \"output_dir\": \"tmp/\", \"resource_id\": \"volc.bigasr.sauc.duration\", \"access_token\": \"\", \"end_window_size\": 200, \"enable_multilingual\": false}','https://console.volcengine.com/speech/app','豆包ASR配置说明：\n1. 豆包ASR和豆包(流式)ASR的区别是：豆包ASR是按次收费，豆包(流式)ASR是按时收费\n2. 一般来说按次收费的更便宜，但是豆包(流式)ASR使用了大模型技术，效果更好\n3. 需要在火山引擎控制台创建应用并获取appid和access_token\n4. 支持中文语音识别\n5. 需要网络连接\n6. 输出文件保存在tmp/目录\n申请步骤：\n1. 访问 https://console.volcengine.com/speech/app\n2. 创建新应用\n3. 获取appid和access_token\n4. 填入配置文件中\n如需设置热词，请参考：https://www.volcengine.com/docs/6561/155738\n如开启多语种识别模式，请设置language当该键为空时，该模型支持中英文、上海话、闽南语，四川、陕西、粤语识别。其他语种请参考：https://www.volcengine.com/docs/6561/1354869\n',5,NULL,NULL,2082117381924220930,'2026-07-29 19:18:03'),('ASR_DoubaoStreamASRV2','ASR','DoubaoStreamASRV2','豆包语音识别2.0(流式)',0,1,'{\"type\": \"doubao_stream\", \"appid\": \"\", \"language\": \"zh-CN\", \"output_dir\": \"tmp/\", \"resource_id\": \"volc.seedasr.sauc.duration\", \"access_token\": \"\", \"end_window_size\": 200, \"enable_multilingual\": false}','https://www.volcengine.com/docs/6561/109979','豆包语音识别模型2.0配置说明（基于火山引擎seed-asr）：\n1. 访问 https://www.volcengine.com/ 注册并开通火山引擎账号\n2. 访问 https://console.volcengine.com/speech/service/10038 开通豆包流式语音识别模型2.0\n3. 在页面底部获取appid和access_token\n4. 资源ID有两种：小时版（volc.seedasr.sauc.duration）和并发版（volc.seedasr.sauc.concurrent）\n   - 小时版：固定为：volc.seedasr.sauc.duration（豆包语音识别模型2.0）\n   - 并发版：固定为：volc.seedasr.sauc.concurrent（豆包语音识别模型2.0）\n\n详细参数文档：https://www.volcengine.com/docs/6561/109979\n\n注意：\n- 豆包语音识别模型2.0使用volc.seedasr.sauc.duration资源ID，与豆包语音识别(流式)（volc.bigasr.sauc.duration）不同\n- 语音识别模型2.0价格更为便宜，建议在高并发场景下使用并发版资源ID\n',6,NULL,NULL,2082117381924220930,'2026-07-29 19:18:03'),('ASR_FunASR','ASR','FunASR','FunASR语音识别',0,1,'{\"type\": \"fun_local\", \"language\": \"auto\", \"model_dir\": \"models/SenseVoiceSmall\", \"output_dir\": \"tmp/\"}','https://github.com/modelscope/FunASR','FunASR本地模型配置说明：\n1. 需要下载模型文件到xiaozhi-server/models/SenseVoiceSmall目录\n2. 支持中日韩粤语音识别\n3. 本地推理，无需网络连接\n4. 待识别文件保存在tmp/目录\n5. “识别语言”字段控制识别语种：auto = 自动检测；如需限定只识别中文可设为 zh（en=英语、ja=日语、ko=韩语、yue=粤语）。',1,NULL,NULL,2082117381924220930,'2026-07-29 19:18:03'),('ASR_FunASRServer','asr','FunASRServer','FunASR服务语音识别',0,1,'{\"host\": \"82.156.31.182\", \"port\": \"10095\", \"type\": \"fun_server\", \"is_ssl\": true, \"api_key\": \"none\", \"output_dir\": \"tmp/\"}','https://github.com/modelscope/FunASR/blob/main/runtime/docs/SDK_advanced_guide_online_zh.md','独立部署FunASR，使用FunASR的API服务，只需要五句话\n第一句：mkdir -p ./funasr-runtime-resources/models\n第二句：sudo docker run -d -p 10096:10095 --privileged=true -v $PWD/funasr-runtime-resources/models:/workspace/models registry.cn-hangzhou.aliyuncs.com/funasr_repo/funasr:funasr-runtime-sdk-online-cpu-0.1.12\n上一句话执行后会进入到容器，继续第三句：cd FunASR/runtime\n不要退出容器，继续在容器中执行第四句：nohup bash run_server_2pass.sh --download-model-dir /workspace/models --vad-dir damo/speech_fsmn_vad_zh-cn-16k-common-onnx --model-dir iic/SenseVoiceSmall-onnx  --online-model-dir damo/speech_paraformer-large_asr_nat-zh-cn-16k-common-vocab8404-online-onnx  --punc-dir damo/punc_ct-transformer_zh-cn-common-vad_realtime-vocab272727-onnx --lm-dir damo/speech_ngram_lm_zh-cn-ai-wesp-fst --itn-dir thuduj12/fst_itn_zh --hotword /workspace/models/hotwords.txt > log.txt 2>&1 &\n上一句话执行后会进入到容器，继续第五句：tail -f log.txt\n第五句话执行完后，会看到模型下载日志，下载完后就可以连接使用了\n以上是使用CPU推理，如果有GPU，详细参考：https://github.com/modelscope/FunASR/blob/main/runtime/docs/SDK_advanced_guide_online_zh.md',2,NULL,NULL,2082117381924220930,'2026-07-29 19:18:03'),('ASR_FunASRServer2Pass','ASR','FunASRServer2Pass','FunASRServer2Pass',1,1,'{\"itn\": false, \"host\": \"82.156.31.182\", \"mode\": \"2pass\", \"port\": \"10095\", \"type\": \"fun_server_2pass\", \"is_ssl\": true, \"api_key\": \"none\", \"hotwords\": {\"林晓锋\": 30, \"中科生创\": 20}, \"chunk_size\": [5, 10, 5], \"output_dir\": \"tmp/\", \"recv_timeout\": 8, \"chunk_interval\": 10, \"text_corrections\": {\"林晓峰\": \"林晓锋\"}}','https://github.com/modelscope/FunASR/blob/main/runtime/docs/SDK_advanced_guide_online_zh.md','FunASR runtime 2-pass streaming provider; starts websocket at VAD speech start and consumes final 2pass-offline result.',22,NULL,'2026-07-29 11:49:51',2082117381924220930,'2026-07-29 21:42:40'),('ASR_GroqASR','ASR','GroqASR','Groq语音识别',0,1,'{\"type\": \"openai\", \"api_key\": \"\", \"base_url\": \"https://api.groq.com/openai/v1/audio/transcriptions\", \"model_name\": \"whisper-large-v3-turbo\", \"output_dir\": \"tmp/\"}','https://console.groq.com/docs/speech-to-text','Groq ASR配置说明：\n1.登录groq Console。https://console.groq.com/home\n2.创建api-key  https://console.groq.com/keys\n3.模型可以选择whisper-large-v3-turbo或whisper-large-v3（distil-whisper-large-v3-en仅支持英语转录）\n',12,NULL,NULL,2082117381924220930,'2026-07-29 19:18:03'),('ASR_OpenaiASR','ASR','OpenaiASR','OpenAI语音识别',0,1,'{\"type\": \"openai\", \"api_key\": \"\", \"base_url\": \"https://api.openai.com/v1/audio/transcriptions\", \"model_name\": \"gpt-4o-mini-transcribe\", \"output_dir\": \"tmp/\"}','https://platform.openai.com/docs/api-reference/audio/createTranscription','OpenAI ASR配置说明：\n1. 需要在OpenAI开放平台创建组织并获取api_key\n2. 支持中、英、日、韩等多种语音识别，具体参考文档https://platform.openai.com/docs/guides/speech-to-text\n3. 需要网络连接\n4. 输出文件保存在tmp/目录\n申请步骤：\n**OpenAi ASR申请步骤：**\n1.登录OpenAI Platform。https://auth.openai.com/log-in\n2.创建api-key  https://platform.openai.com/settings/organization/api-keys\n3.模型可以选择gpt-4o-transcribe或GPT-4o mini Transcribe\n',11,NULL,NULL,2082117381924220930,'2026-07-29 19:18:03'),('ASR_Qwen3Flash','ASR','Qwen3-ASR-Flash','Qwen3Flash语音识别',0,1,'{\"type\": \"qwen3_asr_flash\", \"api_key\": \"\", \"base_url\": \"https://dashscope.aliyuncs.com/compatible-mode/v1\", \"enable_itn\": true, \"enable_lid\": true, \"model_name\": \"qwen3-asr-flash\", \"output_dir\": \"tmp/\"}','https://bailian.console.aliyun.com/?apiKey=1&tab=doc#/doc/?type=model&url=2979031','通义千问Qwen3-ASR-Flash配置说明：\n1. 登录阿里云百炼平台https://bailian.console.aliyun.com/\n2. 创建API-KEY  https://bailian.console.aliyun.com/#/api-key\n3.Qwen3-ASR-Flash基于通义千问多模态基座，支持多语言识别、歌唱识别、噪声拒识等功能\n',14,NULL,NULL,2082117381924220930,'2026-07-29 19:18:03'),('ASR_SherpaASR','ASR','SherpaASR','Sherpa语音识别',0,1,'{\"type\": \"sherpa_onnx_local\", \"model_dir\": \"models/sherpa-onnx-sense-voice-zh-en-ja-ko-yue-2024-07-17\", \"output_dir\": \"tmp/\"}','https://github.com/k2-fsa/sherpa-onnx','SherpaASR配置说明：\n1. 运行时自动下载模型文件到models/sherpa-onnx-sense-voice-zh-en-ja-ko-yue-2024-07-17目录\n2. 支持中文、英文、日语、韩语、粤语等多种语言\n3. 本地推理，无需网络连接\n4. 输出文件保存在tmp/目录',10,NULL,NULL,2082117381924220930,'2026-07-29 19:18:03'),('ASR_TencentASR','ASR','TencentASR','腾讯语音识别',0,1,'{\"type\": \"tencent\", \"appid\": \"\", \"secret_id\": \"\", \"output_dir\": \"tmp/\", \"secret_key\": \"你的secret_key\"}','https://console.cloud.tencent.com/cam/capi','腾讯ASR配置说明：\n1. 需要在腾讯云控制台创建应用并获取appid、secret_id和secret_key\n2. 支持中文语音识别\n3. 需要网络连接\n4. 输出文件保存在tmp/目录\n申请步骤：\n1. 访问 https://console.cloud.tencent.com/cam/capi 获取密钥\n2. 访问 https://console.cloud.tencent.com/asr/resourcebundle 领取免费资源\n3. 获取appid、secret_id和secret_key\n4. 填入配置文件中',6,NULL,NULL,2082117381924220930,'2026-07-29 19:18:03'),('ASR_VoskASR','ASR','VoskASR','VOSK离线语音识别',0,1,'{\"type\": \"vosk\", \"model_path\": \"\", \"output_dir\": \"tmp/\"}','https://alphacephei.com/vosk/','VOSK ASR配置说明：\n1. VOSK是一个离线语音识别库，支持多种语言\n2. 需要先下载模型文件：https://alphacephei.com/vosk/models\n3. 中文模型推荐使用vosk-model-small-cn-0.22或vosk-model-cn-0.22\n4. 完全离线运行，无需网络连接\n5. 输出文件保存在tmp/目录\n使用步骤：\n1. 访问 https://alphacephei.com/vosk/models 下载中文模型\n2. 解压模型文件到项目目录下的models/vosk/文件夹\n3. 在配置中指定正确的模型路径\n4. 注意：VOSK中文模型输出不带标点符号，词与词之间会有空格\n',13,NULL,NULL,2082117381924220930,'2026-07-29 19:18:03'),('ASR_XunfeiStream','ASR','XunfeiStreamASR','讯飞语音识别(流式)',0,1,'{\"dwa\": \"wpgs\", \"type\": \"xunfei_stream\", \"accent\": \"mandarin\", \"app_id\": \"\", 